def recall(self, observation: str, phase: str) -> list[str]:
    query = f"{self.label} {phase}: {observation[:300]}"
    snippets: list[str] = []
    for scope in ({"agent_id": self.agent_id},
                  {"user_id": self.arena_user_id}):
        try:
            kw: dict[str, Any] = dict(method=self.search_method,
                                      top_k=self.memory_top_k, **scope)
            if self.min_score is not None:
                kw["min_score"] = self.min_score
            data = self.memory.search(query, **kw) or {}
        except Exception:
            self.memory_errors += 1
            continue
        for kind in ("agent_skills", "agent_cases", "episodes"):
            for item in data.get(kind) or []:
                text = _snippet(item)
                if text:
                    # Filter out snippets from failed episodes when better alternatives exist
                    session_id = item.get("session_id")
                    if session_id and session_id in self._session_aers:
                        # Get the best (highest) AER from all sessions we know about
                        best_aer = max(self._session_aers.values()) if self._session_aers else 0.0
                        session_aer = self._session_aers[session_id]
                        # Skip this snippet if it's from a failed/session and we have better
                        if session_aer < best_aer and best_aer > 0:
                            continue
                    snippets.append(text)
    return list(dict.fromkeys(snippets))[:self.memory_top_k]
